const CONTRACT_V10_PAGE="<!doctype html>\n<html lang=\"en\" data-app=\"contract\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"color-scheme\" content=\"dark\"><meta name=\"theme-color\" content=\"#090b10\"><meta name=\"description\" content=\"Run four qualified offline EVM bytecode scenarios using the pinned EthereumJS engine. Inspect gas, return data, errors and opcode traces. No wallet or chain connection.\"><title>Daniel Contract Lab — Offline EVM Execution</title><link rel=\"icon\" href=\"/favicon.ico\"><style>\n:root{color-scheme:dark;--bg:#090b10;--panel:#11151c;--panel2:#171d26;--ink:#f6f8ff;--muted:#aeb9ca;--line:#313c4c;--accent:#b1d1ff;--soft:#283c5e;--success:#e2f0ff;font:16px/1.52 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse 100% 50% at 100% 0%,#17243c 0%,transparent 58%),var(--bg);color:var(--ink);max-width:100%;overflow-x:clip}button,a,input{font:inherit}button{cursor:pointer}a{color:inherit}.wrap{width:min(1280px,calc(100% - 36px));margin:auto}.skip{position:absolute;top:-90px;background:white;color:black;padding:12px;z-index:5}.skip:focus{top:4px}.top{border-bottom:1px solid var(--line);background:#10151dd9}.top-inner{min-height:68px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px}.brand{text-decoration:none;font-weight:820;letter-spacing:-.05em;font-size:16px}.brand span{color:#a5bddc}.nav{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.nav a{text-decoration:none;border:1px solid transparent;border-radius:9px;padding:9px 11px;font-size:12px;color:#d3deed}.nav a:hover,.nav a:focus-visible{border-color:#64799b;background:#1a2a42}.nav a[href=\"/#ask\"]{background:#253955;border-color:#6184b1;color:#fff}\n.hero{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(225px,.65fr);gap:26px;align-items:end;padding:39px 0 26px}.eyebrow{font:760 11px/1.4 ui-monospace,Consolas,monospace;color:#afc6e5;letter-spacing:.13em;text-transform:uppercase;margin:0 0 11px}.hero h1{margin:0;font-size:clamp(38px,5.5vw,70px);line-height:1.01;letter-spacing:-.073em;font-weight:770;max-width:790px}.hero h1 em{font-style:normal;color:#b8d4ff}.lead{font-size:15px;color:var(--muted);max-width:730px;margin:17px 0 0;line-height:1.72}.hero .proof-mini{background:#151e2b;border:1px solid #425673;border-radius:15px;padding:16px 19px;min-width:0}.proof-mini span{display:block;color:#b5c4d8;font:760 11px/1.5 ui-monospace,Consolas,monospace;letter-spacing:.07em}.proof-mini strong{display:block;font-size:22px;letter-spacing:-.03em;margin:8px 0;color:white}.proof-mini p{margin:0;color:#b4c0d0;font-size:12px;line-height:1.6}\n.warning{border-left:3px solid var(--accent);background:#141b28;padding:12px 16px;margin:5px 0 22px;color:#d0dbec;font-size:12px;line-height:1.6;border-radius:0 10px 10px 0}\n.workspace{display:grid;grid-template-columns:minmax(270px,.76fr) minmax(0,1.24fr);gap:13px;align-items:start;margin:0 0 28px}.panel{min-width:0;border-radius:16px;border:1px solid var(--line);background:var(--panel);padding:19px}.panel-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:14px}.panel-heading h2{font-size:19px;letter-spacing:-.04em;line-height:1.2;margin:0}.panel-heading span{font:720 10px/1.4 ui-monospace,Consolas,monospace;color:#a4b9d5;letter-spacing:.04em}\n.options{display:grid;gap:9px}.scenario{width:100%;text-align:left;border:1px solid #354154;border-radius:12px;background:#161e2b;color:#fafbff;min-height:86px;padding:13px;display:grid;grid-template-columns:34px minmax(0,1fr);align-items:start;gap:11px;transition:background .18s,border-color .18s,transform .18s}.scenario .num{width:32px;height:32px;border:1px solid #536986;border-radius:8px;display:grid;place-items:center;color:#adbed5;font:750 12px ui-monospace,Consolas,monospace}.scenario strong{font-size:13px;letter-spacing:-.012em;display:block}.scenario small{display:block;font-size:11px;line-height:1.5;color:#a8b6ca;margin-top:5px}.scenario:hover{background:#1f2e45;border-color:#839fc6;transform:translateY(-1px)}.scenario[aria-pressed=\"true\"]{border-color:#bfd8ff;background:#233651;box-shadow:inset 3px 0 0 #c4dcff}.scenario[aria-pressed=\"true\"] .num{background:#d5e5ff;color:#0b1730}.scenario:disabled{cursor:wait;opacity:.7}\n.actions{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;margin:15px 0 0}.btn{min-height:47px;border-radius:10px;border:1px solid #5d7191;padding:11px 14px;background:#24344c;color:#edf5ff;font-weight:740;font-size:12px}.btn.primary{background:#d7e8ff;color:#0a182d;border-color:#d7e8ff}.btn:hover:not(:disabled){filter:brightness(1.13)}.btn:disabled{opacity:.5;cursor:wait}.status{display:block;min-height:37px;color:#c2d3eb;margin:11px 0 0;line-height:1.5;font-size:12px;overflow-wrap:anywhere}.status[data-verdict=\"pass\"]{color:#e9f5ff}.status[data-verdict=\"fail\"]{color:#ffd3d3}\n.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin-bottom:12px}.metric{background:#171e2a;border:1px solid #34445a;border-radius:10px;padding:13px 11px;min-width:0}.metric span{display:block;font:710 10px/1.4 ui-monospace,Consolas,monospace;color:#aebcd0;letter-spacing:.07em;text-transform:uppercase}.metric strong{display:block;font-size:clamp(18px,2vw,27px);line-height:1.26;letter-spacing:-.035em;margin-top:7px;overflow-wrap:anywhere}.metric small{display:block;color:#a9b6c6;font-size:11px}\n.rail{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin-bottom:14px}.rail-item{display:grid;gap:5px;background:#171f2d;border:1px solid #394b65;border-radius:9px;padding:11px}.rail-item b{font:750 11px ui-monospace,Consolas,monospace;color:#c0d8ff}.rail-item span{font-size:11px;color:#bbcbdf}.rail-item[data-ok=\"true\"]{background:#223c5c;border-color:#7399c7}\n.excerpt{border-radius:11px;border:1px solid #465571;background:#0b1019;padding:15px;margin-bottom:12px}.excerpt-head{display:flex;justify-content:space-between;gap:8px;align-items:center;margin-bottom:8px}.excerpt-head h3{font-size:13px;margin:0;letter-spacing:-.01em}.excerpt-head span{font:710 10px ui-monospace,Consolas,monospace;color:#98b9ea}.code{margin:0;color:#cde4ff;overflow-wrap:anywhere;word-break:break-word;white-space:pre-wrap;font:13px/1.8 ui-monospace,SFMono-Regular,Consolas,monospace}\n.results{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:11px}.result-section{min-width:0;border:1px solid #394b63;border-radius:11px;padding:13px;background:#171e2a}.result-section h3{font-size:12px;line-height:1.4;margin:0 0 8px;color:#dbe8fa}.result-section pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:205px;overflow:auto;color:#b5c9e4;margin:0;font:11px/1.65 ui-monospace,Consolas,monospace}.trace-list{list-style:none;padding:0;margin:0;display:grid;gap:5px;max-height:220px;overflow:auto;scrollbar-width:thin}.trace-list li{display:flex;justify-content:space-between;gap:12px;align-items:baseline;background:#1f2a39;padding:8px;border-radius:7px;min-width:0}.trace-list b{font:750 11px ui-monospace,Consolas,monospace}.trace-list span{font:11px ui-monospace,Consolas,monospace;color:#b1c6e3}\n.receipt-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.receipt-actions .btn{flex:1 1 115px}.receipt-actions button:disabled{opacity:.48}\n.sidebar-foot{font-size:11px;line-height:1.6;color:#aabbd0;border-top:1px solid #354357;margin-top:18px;padding-top:14px}\n.footer{border-top:1px solid #253348;padding:25px 0 110px;color:#a9bcd4;font-size:12px}.footer a{color:#d7e8ff}\n:focus-visible{outline:3px solid #a3caff;outline-offset:3px}button,summary{touch-action:manipulation}\n@media(max-width:930px){.hero{grid-template-columns:minmax(0,1fr)}.workspace{grid-template-columns:minmax(0,1fr)}.rail{grid-template-columns:repeat(3,minmax(0,1fr))}}\n@media(max-width:540px){.wrap{width:calc(100% - 24px)}.hero{padding-top:25px}.hero h1{font-size:clamp(35px,9vw,51px)}.panel{padding:14px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.results{grid-template-columns:minmax(0,1fr)}.rail-item{padding:9px}.actions{grid-template-columns:minmax(0,1fr) auto}.nav{gap:0}.top-inner{padding:10px 0}.brand{font-size:14px}}\n@media(prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important;scroll-behavior:auto!important;transform:none!important}}\n@media print{.top,.actions,.receipt-actions{display:none!important}}\n</style></head>\n<body><a class=\"skip\" href=\"#contract-main\">Skip to Contract Lab</a>\n<header class=\"top\"><div class=\"wrap top-inner\"><a class=\"brand\" href=\"/\">DANIEL<span> / </span>ENGINEERING</a><nav class=\"nav\" aria-label=\"Application navigation\"><a href=\"/apps/\">All ten apps ↗</a><a href=\"/apps/evidence/\">Proof</a><a href=\"/#ask\">Ask Daniel ↗</a></nav></div></header>\n<main class=\"wrap\" id=\"contract-main\">\n<section class=\"hero\"><div><p class=\"eyebrow\">APPLICATION 08 / VERIFIED OFFLINE BYTECODE</p><h1>Read the execution.<br><em>Trust the evidence.</em></h1><p class=\"lead\">Run a real, pinned EthereumJS EVM directly in this browser. Compare expected invariants with observed gas, return data, opcode steps and intentional failures. Every scenario is fully offline, bounded and reproducible.</p></div><aside class=\"proof-mini\"><img src=\"/assets/portrait.jpg\" alt=\"Jemuel Daniel — full-color portrait\" width=\"64\" height=\"64\" style=\"width:64px;height:64px;border-radius:50%;object-fit:cover;border:2px solid #b4d4ff;filter:none;float:right;margin-left:12px\"><span>EXECUTION ENVIRONMENT</span><strong>EthereumJS EVM 10.1.3</strong><p>Prague ruleset · 4 allowlisted scenarios · Zero RPC, wallet signatures or live blockchain transactions.</p></aside></section>\n<p class=\"warning\"><strong>Not a cryptocurrency service.</strong> Runs predetermined raw EVM bytecode only. No deployed contract, blockchain state, Solidity compiler, asset transfer or public transaction is created. This is a qualified *bounded* EVM execution demonstration—not a full audit of arbitrary smart contracts.</p>\n<div class=\"workspace\">\n<section class=\"panel\" aria-labelledby=\"choose-heading\"><div class=\"panel-heading\"><h2 id=\"choose-heading\">01 / Select a scenario</h2><span>PINNED INPUTS</span></div>\n<div class=\"options\" role=\"group\" aria-label=\"Offline EVM examples\">\n<button class=\"scenario\" type=\"button\" data-case=\"arithmetic\" aria-pressed=\"true\"><span class=\"num\">01</span><span><strong>Arithmetic return</strong><small>MUL → MSTORE → RETURN. Inspect the actual word 42.</small></span></button>\n<button class=\"scenario\" type=\"button\" data-case=\"invariant\" aria-pressed=\"false\"><span class=\"num\">02</span><span><strong>Invariant rejection</strong><small>Explicit REVERT, with no successful returned word.</small></span></button>\n<button class=\"scenario\" type=\"button\" data-case=\"condition\" aria-pressed=\"false\"><span class=\"num\">03</span><span><strong>Conditional proof</strong><small>ISZERO produces the EVM's 256-bit true value.</small></span></button>\n<button class=\"scenario\" type=\"button\" data-case=\"gas\" aria-pressed=\"false\"><span class=\"num\">04</span><span><strong>Gas boundary</strong><small>Insufficient gas triggers an actual EVM exception.</small></span></button>\n</div>\n<div class=\"actions\"><button id=\"runSelected\" type=\"button\" class=\"btn primary\">Run selected scenario ↗</button><button id=\"runAll\" type=\"button\" class=\"btn\">Run all 4</button></div>\n<p id=\"runStatus\" class=\"status\" role=\"status\" aria-live=\"polite\">Ready. No EVM code has been executed yet.</p>\n<p class=\"sidebar-foot\">Fixed inputs prevent arbitrary calls, network access and unbounded loops. Each click creates an independent state-isolated EVM execution. <a href=\"/apps/code/\">Explore Code Lab ↗</a></p></section>\n<section class=\"panel\" aria-labelledby=\"run-heading\"><div class=\"panel-heading\"><h2 id=\"run-heading\">02 / Live execution</h2><span id=\"runLabel\">IDLE · NOT RUN</span></div>\n<div class=\"metrics\"><div class=\"metric\"><span>Gas used</span><strong id=\"gasUsed\">—</strong><small id=\"gasLimit\">Limit —</small></div><div class=\"metric\"><span>Return word</span><strong id=\"returnWord\">—</strong><small>EVM 256-bit value</small></div><div class=\"metric\"><span>Opcodes</span><strong id=\"stepsCount\">0</strong><small>Observed execution steps</small></div><div class=\"metric\"><span>Invariant</span><strong id=\"verdict\">Pending</strong><small>Actual execution result</small></div></div>\n<div class=\"rail\" aria-label=\"Observed execution progress\"><div class=\"rail-item\" data-phase=\"load\"><b>01 / BYTECODE</b><span>Awaiting selection</span></div><div class=\"rail-item\" data-phase=\"execute\"><b>02 / EVM</b><span>Not executed</span></div><div class=\"rail-item\" data-phase=\"verify\"><b>03 / INVARIANT</b><span>Not verified</span></div></div>\n<div class=\"excerpt\"><div class=\"excerpt-head\"><h3>Exact bytecode</h3><span id=\"byteCount\">0 BYTES</span></div><pre class=\"code\" id=\"bytecode\">Select an approved scenario.</pre></div>\n<div class=\"results\"><section class=\"result-section\"><h3>Opcode-by-opcode trace</h3><ol class=\"trace-list\" id=\"traceList\"><li><span>No execution yet.</span></li></ol></section><section class=\"result-section\"><h3>Verified execution receipt</h3><pre id=\"receipt\" tabindex=\"0\" aria-label=\"Offline EVM result receipt\">No receipt until a scenario has actually executed.</pre></section></div>\n<div class=\"receipt-actions\"><button type=\"button\" class=\"btn\" id=\"copyReceipt\" disabled>Copy receipt</button><button type=\"button\" class=\"btn\" id=\"downloadReceipt\" disabled>Export proof JSON</button></div></section>\n</div>\n</main>\n<footer class=\"footer\"><div class=\"wrap\">Daniel Contract Lab · Open, bounded offline bytecode verification with EthereumJS · <a href=\"/apps/\">All engineering apps</a> · <a href=\"https://github.com/jemueldaniel/danielcodes\">Review public source</a></div></footer>\n<script type=\"module\" src=\"/apps/contract/app.js\"></script>\n</body></html>";
