/* SOCIAL_V15_COMPILED_START */
const SOCIAL_V15_PANEL="<section class=\"social-v15-board\" aria-labelledby=\"socialV15Title\">\n <div class=\"social-v15-kicker\">RELATIONSHIP INSPECTOR <span>01 / 02</span></div>\n <h3 id=\"socialV15Title\">Connections in motion</h3>\n <p class=\"social-v15-hint\">Two fictional identities. The relationship edges below are computed from your actual actions in this tab.</p>\n <div class=\"social-v15-graph\" aria-label=\"Live simulated social relationship graph\">\n   <div class=\"social-v15-person\"><span class=\"social-v15-monogram\">A</span><span>Avery</span></div>\n   <div class=\"social-v15-edges\"><span id=\"edgeAtoB\" class=\"social-v15-edge\">A → B · not following</span><span id=\"edgeBtoA\" class=\"social-v15-edge\">B → A · not following</span></div>\n   <div class=\"social-v15-person\"><span class=\"social-v15-monogram\">M</span><span>Morgan</span></div>\n </div>\n <div class=\"social-v15-metrics\" aria-label=\"Live interaction counters\">\n   <div><strong id=\"v15Edges\">0</strong><span>follow edges</span></div>\n   <div><strong id=\"v15Replies\">0</strong><span>replies</span></div>\n   <div><strong id=\"v15Saves\">0</strong><span>saved posts</span></div>\n </div>\n</section>\n<section class=\"social-v15-board social-v15-activity\" aria-labelledby=\"socialV15Activity\">\n <div class=\"social-v15-kicker\">ACTION EVIDENCE <span>SESSION ONLY</span></div>\n <h3 id=\"socialV15Activity\">Activity & proof</h3>\n <p class=\"social-v15-hint\">A bounded record of actions that actually saved. Reload this tab to inspect continuity. Export contains only summary counts and event labels, not the text of posts.</p>\n <ol id=\"v15EventList\" class=\"social-v15-events\" aria-live=\"polite\"></ol>\n <div class=\"social-v15-actions\">\n   <button type=\"button\" id=\"v15Download\" class=\"social-v15-action\">↓ Download proof JSON</button>\n   <button type=\"button\" id=\"v15ClearLog\" class=\"social-v15-action\">Clear action log</button>\n </div>\n <p id=\"v15ProofStatus\" role=\"status\" class=\"social-v15-hint social-v15-result\"></p>\n</section>";
const SOCIAL_V15_CSS="/* Original social relationship inspector: scoped, no modal, no remote assets. */\nhtml[data-app=\"social\"]{color-scheme:dark;--bg:#0a0e15!important;--panel:#101827!important;--ink:#f8fafc!important;--soft:#182131!important;--line:#354158!important;--sub:#bdc7d8!important;--tint:#d4e2f7;--accent:#bed8ff!important;--glow:rgba(190,216,255,.08)}\nhtml[data-app=\"social\"] body{background:var(--bg)!important;color:var(--ink)!important}\n.social-v15-board{min-width:0;margin-top:12px;padding:18px 16px;border:1px solid #344157;border-radius:16px;background:#101827}\n.social-v15-board h3{margin:7px 0 9px;font-size:20px;letter-spacing:-.045em;line-height:1.17;color:#fff}\n.social-v15-kicker{display:flex;justify-content:space-between;gap:9px;font:750 10px/1.4 ui-monospace,monospace;letter-spacing:.11em;color:#bed8ff}\n.social-v15-kicker span{color:#9ba9bd;letter-spacing:.02em}\n.social-v15-hint{font-size:12px;line-height:1.6;color:#b8c4d6;margin:7px 0 14px}\n.social-v15-graph{display:grid;grid-template-columns:minmax(0,1fr) minmax(112px,1.45fr) minmax(0,1fr);align-items:center;gap:8px;padding:18px 8px;border:1px solid #2c3950;border-radius:13px;background:radial-gradient(ellipse at 50% 25%,rgba(190,216,255,.09),transparent 70%),#0b101a}\n.social-v15-person{display:grid;justify-items:center;gap:8px;min-width:0;font-size:11px;font-weight:750;color:#e6edf7}\n.social-v15-monogram{width:clamp(40px,5vw,53px);height:clamp(40px,5vw,53px);border-radius:50%;display:grid;place-items:center;border:1px solid #d8e3f3;background:#e3e9f3;color:#0b101a;font-size:20px;font-weight:790;box-shadow:0 0 0 5px rgba(190,216,255,.05)}\n.social-v15-edges{display:grid;gap:9px;min-width:0}\n.social-v15-edge{display:block;min-width:0;padding:8px 4px;border:1px solid #394960;background:#171f2e;border-radius:999px;text-align:center;color:#aeb9c9;font-size:10px;line-height:1.3;overflow-wrap:anywhere;transition:background .2s,border-color .2s,color .2s}\n.social-v15-edge[data-connected=\"true\"]{border-color:#bed8ff;background:#293852;color:#fff;font-weight:800}\n.social-v15-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));margin-top:12px;border:1px solid #2f3b50;border-radius:12px;overflow:hidden}\n.social-v15-metrics div{display:grid;gap:4px;justify-items:center;padding:12px 5px;background:#141d2b}\n.social-v15-metrics div+div{border-left:1px solid #2f3b50}\n.social-v15-metrics strong{color:#fff;font-size:22px;font-weight:750;font-variant-numeric:tabular-nums}\n.social-v15-metrics span{font-size:10px;color:#b6c3d5;text-align:center}\n.social-v15-events{list-style:none;counter-reset:e;display:grid;gap:7px;margin:0;padding:0;max-height:186px;overflow:auto}\n.social-v15-events li{display:grid;grid-template-columns:52px minmax(0,1fr);gap:9px;padding:9px 10px;border:1px solid #303d53;border-radius:9px;background:#161f2e;color:#e9eef7;font-size:11px;line-height:1.55;overflow-wrap:anywhere}\n.social-v15-events time{color:#a0aec3;font-variant-numeric:tabular-nums}\n.social-v15-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:13px}\n.social-v15-action{min-height:44px;padding:9px 8px;border:1px solid #54647d;border-radius:10px;background:#1b283a;color:#fff;font:730 11px/1.3 ui-sans-serif,system-ui;cursor:pointer}\n.social-v15-action:hover{background:#273850;border-color:#b6d0f4}\n.social-v15-action:active{transform:scale(.98)}\n.social-v15-action:focus-visible{outline:3px solid #fff;outline-offset:3px}\n.social-v15-result{min-height:20px;margin-bottom:0}\n/* Intentional, native CSS motion: only graph connections and committed actions move. */\n.social-v15-board{animation:social-v15-appear .52s cubic-bezier(.2,.8,.2,1) both}\n.social-v15-activity{animation-delay:.09s}\n.social-v15-edge[data-connected=\"true\"]{background-image:linear-gradient(105deg,#26354c 0%,#3c526e 48%,#26354c 100%);background-size:240% 100%;animation:social-v15-connection 3.5s ease-in-out infinite alternate}\n.social-v15-monogram{transition:transform .35s cubic-bezier(.2,.8,.2,1),box-shadow .35s ease}\n.social-v15-events li:first-child{animation:social-v15-event .3s cubic-bezier(.16,1,.3,1) both}\n.social-v15-metrics strong{display:inline-block;will-change:auto}\n.social-v15-action{transition:transform .2s cubic-bezier(.2,.8,.2,1),background .2s,border-color .2s}\n@media(hover:hover) and (pointer:fine){.social-v15-graph:hover .social-v15-monogram{transform:translateY(-3px);box-shadow:0 7px 18px rgba(190,216,255,.12)}.social-v15-action:hover{transform:translateY(-2px)}}\n@keyframes social-v15-appear{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}\n@keyframes social-v15-connection{from{background-position:100% 50%}to{background-position:0 50%}}\n@keyframes social-v15-event{from{opacity:.3;transform:translateY(-5px)}to{opacity:1;transform:translateY(0)}}\nhtml[data-app=\"social\"] #resetSocial[data-confirming=\"true\"]{background:#eef2f7!important;color:#101827!important;border-color:#fff!important}\n@media(max-width:710px){.social-v15-board{padding:15px}.social-v15-graph{gap:3px}.social-v15-edge{font-size:9px;padding:8px 3px}}\n@media(max-width:350px){.social-v15-actions{grid-template-columns:1fr}.social-v15-board{padding:12px}.social-v15-graph{grid-template-columns:minmax(0,1fr) minmax(100px,1.2fr) minmax(0,1fr)}}\n@media(prefers-reduced-motion:reduce){.social-v15-board,.social-v15-events li,.social-v15-edge{animation:none!important}.social-v15-monogram,.social-v15-edge,.social-v15-action,.social-v15-metrics strong{transition:none!important;transform:none!important}}";
const SOCIAL_V15_ADDON="/* Original, bounded UI extension inside existing Social IIFE. */\nconst V15_KEY='daniel-social-action-proof-v15';\nlet v15History=[];\ntry {\n const read=JSON.parse(sessionStorage.getItem(V15_KEY)||'[]');\n if(Array.isArray(read))v15History=read.filter(x=>x&&Number.isFinite(x.at)&&x.at>0&&typeof x.event==='string'&&x.event.length<=150).slice(-18);\n} catch {}\nconst v15Text=(id,content)=>{\n const node=$(id),next=String(content);\n if(node.textContent===next)return;\n node.textContent=next;\n if(node.matches('strong')&&typeof node.animate==='function'&&!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches)){\n  node.animate([{transform:'translateY(5px) scale(.94)',opacity:.5},{transform:'translateY(0) scale(1)',opacity:1}],{duration:340,easing:'cubic-bezier(.16,1,.3,1)'});\n }\n};\nfunction v15Refresh(){\n const ab=state.follows.A.includes('B'),ba=state.follows.B.includes('A');\n const edges=[['edgeAtoB','A → B',ab],['edgeBtoA','B → A',ba]];\n edges.forEach(([id,label,follow])=>{const node=$(id);node.textContent=label+(follow?' · following':' · not following');node.dataset.connected=String(follow)});\n v15Text('v15Edges',Number(ab)+Number(ba));\n v15Text('v15Replies',state.posts.reduce((n,p)=>n+p.comments.length,0));\n v15Text('v15Saves',state.bookmarks.A.length+state.bookmarks.B.length);\n const list=$('v15EventList');list.replaceChildren();\n if(!v15History.length){list.append(el('li','No recorded actions. Like, reply, follow, or post to inspect real state changes.'));return}\n v15History.slice().reverse().forEach(item=>{\n   const li=el('li'),date=el('time',new Date(item.at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})),label=el('span',item.event);\n   date.dateTime=new Date(item.at).toISOString();li.append(date,label);list.append(li)\n })\n}\nconst v15OriginalRender=render;\nrender=function(){v15OriginalRender();v15Refresh()};\nconst v15OriginalMutate=mutate;\nmutate=function(fn,message){\n const accepted=v15OriginalMutate(fn,message);\n if(!accepted)return false;\n const record={at:Date.now(),event:(who(active)+': '+message).slice(0,150)};\n v15History.push(record);v15History=v15History.slice(-18);\n try{sessionStorage.setItem(V15_KEY,JSON.stringify(v15History))}catch{v15Text('v15ProofStatus','Action saved; proof log could not persist in this tab.')}\n v15Refresh();return true;\n};\n$('v15Download').addEventListener('click',()=>{\n try{\n  const payload={schema:'daniel-social-tab-proof-v1',scope:'fictional_session_tab',at:new Date().toISOString(),\n   activePersona:who(active),summary:{posts:state.posts.length,replies:state.posts.reduce((n,p)=>n+p.comments.length,0),\n    likes:state.posts.reduce((n,p)=>n+p.likes.length,0),followEdges:state.follows.A.length+state.follows.B.length,\n    saves:state.bookmarks.A.length+state.bookmarks.B.length},\n   relationshipEdges:{averyToMorgan:state.follows.A.includes('B'),morganToAvery:state.follows.B.includes('A')},\n   actionHistory:v15History.slice(),privatePostBodiesExcluded:true,\n   disclaimer:'Browser-local fictional state and timestamps, not server-attested proof of real users or production activity.'};\n  const uri=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));\n  const link=el('a');link.href=uri;link.download='daniel-social-tab-proof.json';document.body.append(link);link.click();link.remove();\n  setTimeout(()=>URL.revokeObjectURL(uri),2000);\n  v15Text('v15ProofStatus','Saved bounded JSON receipt. Post and reply bodies are not included.');\n }catch{v15Text('v15ProofStatus','Browser could not generate a file. Your tab state is unchanged.')}\n});\n$('v15ClearLog').addEventListener('click',()=>{\n try{sessionStorage.removeItem(V15_KEY);v15History=[];v15Refresh();v15Text('v15ProofStatus','Activity log cleared; posts and reactions were preserved.')}\n catch{v15Text('v15ProofStatus','Browser storage denied clearing the action log.')}\n});\nconst v15Reset=$('resetSocial');let v15ResetArmed=false;\nv15Reset.addEventListener('click',event=>{\n if(!v15ResetArmed){\n  event.stopImmediatePropagation();v15ResetArmed=true;\n  v15Reset.dataset.confirming='true';v15Reset.textContent='Confirm reset · all synthetic posts';\n  notice('Click Confirm reset to clear this fictional workspace, or continue using another control.');\n  return;\n }\n v15ResetArmed=false;v15Reset.dataset.confirming='false';v15Reset.textContent='Reset synthetic workspace';\n try{sessionStorage.removeItem(V15_KEY);v15History=[]}catch{}\n queueMicrotask(v15Refresh);\n},true);\nfunction v15DisarmReset(){\n if(!v15ResetArmed)return;\n v15ResetArmed=false;v15Reset.dataset.confirming='false';\n v15Reset.textContent='Reset synthetic workspace';\n}\ndocument.addEventListener('click',event=>{\n if(v15ResetArmed&&!v15Reset.contains(event.target))v15DisarmReset();\n},true);\ndocument.addEventListener('keydown',event=>{\n if(event.key==='Escape')v15DisarmReset();\n},true);\n";
